const __pageData = JSON.parse('{"title":"Barack Obama","description":"","frontmatter":{"title":"Barack Obama","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["presidency","libya","syria","isis","muslim-brotherhood","labor"],"sources":["raw/a-conflict-of-interest.md","raw/a-mysterious-masterclass-in-multi.md","raw/a-more-perfect-labor-union.md","raw/a-swan-song-for-the-msm.md","raw/a-dereliction-of-duty.md","raw/a-virus-or-a-metaphor.md","raw/a-week-to-remember.md","raw/america-for-sale-part-2.md","raw/america-for-sale-part-3.md","raw/and-iran-iran-so-far-away.md","raw/bad-actors.md","raw/badlands-brief-740.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-19b.md","raw/badlands-news-brief-1a0.md","raw/badlands-news-brief-18e.md","raw/badlands-news-brief-1cc.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-321.md","raw/badlands-news-brief-33b.md","raw/badlands-news-brief-3f5.md","raw/badlands-news-brief-3f8.md","raw/badlands-news-brief-447.md","raw/badlands-news-brief-4bb.md","raw/badlands-news-brief-4c5.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-7a5.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-87b.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/barack-obama.md","filePath":"entities/barack-obama.md","lastUpdated":null}');
